import React, { Component } from 'react';
import './googlemap.css';
import AudioPlayer from 'react-h5-audio-player';
import 'react-h5-audio-player/lib/styles.css';

class Map extends Component {
    constructor(props) {
        super(props);
        this.state = {
            selectedTime: '',
            petLocations: [],
            playing: false,
            currentPointIndex: 0,
            intervalId: null,
            currentPhoto: null,
            mapLoaded: false,
            currentTime: new Date(),
        };
        this.map = null;
        this.panorama = null;
    }

    componentDidMount() {
        this.loadScript();
        this.updateTime();
        this.timeInterval = setInterval(this.updateTime, 60000); // עדכון כל דקה

        const urlParams = new URLSearchParams(window.location.search);
        const lat = parseFloat(urlParams.get('lat'));
        const lng = parseFloat(urlParams.get('lng'));
        const pet_id = urlParams.get('pet_id');

        if (lat && lng && pet_id) {
            this.fetchHistory(lat, lng, pet_id);
        }
    }

    componentWillUnmount() {
        const script = document.getElementById('googleMaps');
        if (script) {
            document.head.removeChild(script);
        }
        if (this.state.intervalId) {
            clearInterval(this.state.intervalId);
        }
        clearInterval(this.timeInterval);
    }

    loadScript = () => {
        const existingScript = document.getElementById('googleMaps');
        if (!existingScript) {
            const script = document.createElement('script');
            script.src = `https://maps.googleapis.com/maps/api/js?key=YOUR_API_KEY&libraries=places&callback=initMap`;
            script.id = 'googleMaps';
            script.async = true;
            script.defer = true;
            window.initMap = this.initMap;
            document.head.appendChild(script);
        } else {
            this.initMap();
        }
    };

    initMap = () => {
        if (window.google && window.google.maps) {
            const fenway = { lat: 32.074572, lng: 34.797105 };
            this.map = new window.google.maps.Map(document.getElementById('map'), {
                zoom: 12,
                center: fenway,
            });

            this.panorama = new window.google.maps.StreetViewPanorama(
                document.getElementById('pano'),
                {
                    position: fenway,
                    pov: {
                        heading: 34,
                        pitch: 10,
                    },
                }
            );

            this.map.setStreetView(this.panorama);
            console.log('Google Maps API loaded successfully.');
            this.setState({ mapLoaded: true });
        } else {
            console.error("Google Maps API failed to load.");
        }
    };

    fetchHistory = (lat, lng, pet_id) => {
        fetch(`http://localhost:3001/locationhistory?pet_id=${pet_id}&lat=${lat}&lng=${lng}`)
            .then((response) => response.json())
            .then((data) => {
                this.setState({ petLocations: data, currentPointIndex: 0, currentPhoto: null }, this.playHistory);
            })
            .catch((error) => console.error('Error fetching location history:', error));
    };

    playHistory = () => {
        if (!this.state.playing) {
            const intervalId = setInterval(() => {
                const { currentPointIndex, petLocations } = this.state;
                if (currentPointIndex >= petLocations.length) {
                    clearInterval(this.state.intervalId);
                    this.setState({ playing: false });
                    return;
                }

                const point = petLocations[currentPointIndex];
                this.addMarkerAndLine(point);

                const pointTime = new Date(this.state.currentTime);
                pointTime.setMinutes(pointTime.getMinutes() + currentPointIndex);
                this.setState({ currentPointIndex: currentPointIndex + 1, currentTime: pointTime });

                const audio = new Audio('URL_OF_YOUR_DOG_BARK_AUDIO_FILE');
                audio.play();
            }, 60000); // שינוי זמן ההתקדמות ל-60000 מילישניות (1 דקה)

            this.setState({ intervalId, playing: true });
        }
    };

    stopHistory = () => {
        if (this.state.intervalId) {
            clearInterval(this.state.intervalId);
            this.setState({ playing: false, intervalId: null });
        }
    };

    addMarkerAndLine = (point) => {
        const marker = new window.google.maps.Marker({
            position: { lat: parseFloat(point.latitude), lng: parseFloat(point.longitude) },
            map: this.map,
            title: `Pet Location at ${point.timestamp}`,
        });

        if (this.state.currentPointIndex > 0) {
            const previousPoint = this.state.petLocations[this.state.currentPointIndex - 1];
            const line = new window.google.maps.Polyline({
                path: [
                    { lat: parseFloat(previousPoint.latitude), lng: parseFloat(previousPoint.longitude) },
                    { lat: parseFloat(point.latitude), lng: parseFloat(point.longitude) },
                ],
                geodesic: true,
                strokeColor: '#FF0000',
                strokeOpacity: 1.0,
                strokeWeight: 2,
            });
            line.setMap(this.map);
        }

        const service = new window.google.maps.places.PlacesService(this.map);
        const request = {
            location: new window.google.maps.LatLng(point.latitude, point.longitude),
            radius: '50'
        };

        service.nearbySearch(request, (results, status) => {
            if (status === window.google.maps.places.PlacesServiceStatus.OK && results.length > 0) {
                const place = results[0];
                const photoUrl = place.photos && place.photos.length > 0
                    ? place.photos[0].getUrl({ maxWidth: 100, maxHeight: 100 })
                    : '';

                this.setState({
                    currentPhoto: {
                        name: place.name,
                        lat: point.latitude,
                        lng: point.longitude,
                        photoUrl: photoUrl
                    }
                });

                if (window.google.maps.StreetViewService) {
                    const streetViewService = new window.google.maps.StreetViewService();
                    const STREETVIEW_MAX_DISTANCE = 50;

                    streetViewService.getPanorama({
                        location: new window.google.maps.LatLng(point.latitude, point.longitude),
                        radius: STREETVIEW_MAX_DISTANCE
                    }, this.processStreetViewData);
                } else {
                    console.error('StreetViewService is not available.');
                }
            } else {
                console.error('Nearby search failed or no photos available:', status);
            }
        });
    };

    processStreetViewData = (data, status) => {
        if (status === window.google.maps.StreetViewStatus.OK) {
            this.panorama.setPosition(data.location.latLng);
            this.panorama.setPov({
                heading: 34,
                pitch: 10,
            });
        } else {
            console.error('Street View data not found for this location.');
        }
    };

    updateTime = () => {
        this.setState({ currentTime: new Date() });
    };

    render() {
        const { currentTime } = this.state;
        const formattedTime = currentTime.toLocaleTimeString();

        return (
            <div className="app-container">
                <div className="content-container-2">
                    <div className="sidebar">
                        <select onChange={this.handleTimeChange} value={this.state.selectedTime}>
                            <option value="">Select Time Period</option>
                            {Array.from({ length: 24 }, (_, i) => (
                                <option key={i + 1} value={`last ${i + 1} hours`}>{`Last ${i + 1} hours`}</option>
                            ))}
                            <option value="last day">Last Day</option>
                            <option value="last week">Last Week</option>
                        </select>
                        <button className='show' onClick={this.showHistory}>Show History</button>
                        <div className='audiomapcontainer'>
                            <div id="pano" className="map-streetview-container">
                                <div className="datetime-overlay">{formattedTime}</div>
                            </div>
                            {this.state.mapLoaded && (
                                <div className="audio-player-overlay">
                                    <AudioPlayer
                                        src="URL_OF_YOUR_AUDIO_FILE"
                                        onPlay={this.playHistory}
                                        onPause={this.stopHistory}
                                        showJumpControls={false}
                                        customAdditionalControls={[]}
                                    />
                                </div>
                            )}
                        </div>
                    </div>
                    <div id="map" className="map-container"></div>
                    {this.state.currentPhoto && this.state.currentPhoto.photoUrl && (
                        <div className="map-photo-container">
                            <img src={this.state.currentPhoto.photoUrl} alt={this.state.currentPhoto.name} className="small-photo" />
                            <h3>{this.state.currentPhoto.name}</h3>
                            <p>Latitude: {this.state.currentPhoto.lat}</p>
                            <p>Longitude: {this.state.currentPhoto.lng}</p>
                        </div>
                    )}
                </div>
            </div>
        );
    }
}

export default Map;
